SELECT ('00000000-0000-0000-0000-'||lpad((10+i)::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000002',i,'00000000-0000-0000-0000-000000000004',CASE WHEN i IN (3,4) THEN 'queued' ELSE 'active' END,'Fixture','00000000-0000-0000-0000-000000000001',1,'2025-01-02T03:04:05.123456Z' FROM generate_series(1,4) i;
SELECT id,1,'{"project_fields":{"threshold":3,"unicode":"é😀"},"control":{"id":"baseline","revision":1}}',1,'00000000-0000-0000-0000-000000000001','api' FROM hypotheses;
SELECT ('00000000-0000-0000-0000-'||lpad((20+i)::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000002',('00000000-0000-0000-0000-'||lpad((10+i)::text,12,'0'))::uuid,1,CASE WHEN i=1 THEN 'claimed' ELSE 'testing' END,1,1,'00000000-0000-0000-0000-000000000004','00000000-0000-0000-0000-000000000001','api','legacy client',1,CASE WHEN i=1 THEN decode(repeat('07',32),'hex') END,CASE WHEN i=1 THEN TIMESTAMPTZ '2025-01-02T03:04:05.123456Z'+interval '60 seconds' END,'{"repo":"fixture","revision":1}',CASE WHEN i=1 THEN '{"steps":[]}'::jsonb END,CASE WHEN i=1 THEN TIMESTAMPTZ '2025-01-02T03:04:05.123456Z'+interval '600 seconds' END,'2025-01-02T03:04:05.123456Z' FROM generate_series(1,2) i;
SELECT '00000000-0000-0000-0000-000000000023',project_id,hypothesis_id,2,'failed',hypothesis_revision,science_revision,track_id,claimed_by_user,via_channel,via_client,lease_generation,claimed_at FROM attempts WHERE id='00000000-0000-0000-0000-000000000022';
SELECT ('00000000-0000-0000-0000-'||lpad((200+i)::text,12,'0'))::uuid,('00000000-0000-0000-0000-'||lpad((21+(i%2))::text,12,'0'))::uuid,'tester','fixture','é 🦀',CASE WHEN i=1 THEN 'null'::jsonb ELSE '{"é":[true,1,null]}'::jsonb END,'2025-01-02T03:04:05Z'::timestamptz+i*interval '1 second',i=2,'[]' FROM generate_series(1,3) i;
SELECT ('00000000-0000-0000-0000-'||lpad((100+i)::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000002',('00000000-0000-0000-0000-'||lpad((21+((i-1)/2))::text,12,'0'))::uuid,CASE WHEN i%2=1 THEN 'tester' ELSE 'evaluator' END,1,CASE WHEN i=6 THEN 'pending' ELSE 'claimed' END,1,'fixture','{}',30,'2025-01-02T03:04:05Z',CASE WHEN i<>6 THEN '00000000-0000-0000-0000-000000000003'::uuid END,CASE WHEN i<>6 THEN decode(lpad(i::text,64,'0'),'hex') END,CASE WHEN i=6 THEN NULL WHEN i IN (1,2) THEN '2000-01-01Z'::timestamptz ELSE '9999-01-01Z'::timestamptz END,CASE WHEN i IN (3,4) THEN '2000-01-01Z'::timestamptz ELSE '9999-01-01Z'::timestamptz END FROM generate_series(1,6) i;
